import { describe, expect, test } from 'bun:test'
import { resolve } from 'node:path'
import { type Condition, ConditionError, type Observation, evaluate, neverWithin, parse, sample } from './conditions'

// PARITY. `watch_cases.json` is generated by wdashboard-server
// (tests/watch/fixtures/gen_watch_cases.py) from the authoritative Python and vendored here
// byte-identical; the Python suite runs the same file (tests/watch/test_cases.py). These two
// tests are the only thing standing between "the replay evaluates watches in the browser"
// and "the browser has its own opinion about when an alert fires".

interface Cases {
  conditions: Array<{ name: string; condition: Condition; now: unknown; previous: unknown; expect: boolean | null }>
  parse: Array<{ name: string; document: unknown; expect: { ok: boolean; normalised?: Condition } }>
}

const cases = (await Bun.file(resolve(import.meta.dir, 'fixtures/watch_cases.json')).json()) as Cases

/** The wire form the fixture writes an observation in: a bare number or string, or
 * `{value, low?, high?}` — the same two spellings `Sample.from_wire` accepts. */
function observation(row: unknown): Observation {
  const out: Observation = {}
  for (const [name, value] of Object.entries(row as Record<string, unknown>)) {
    out[name] =
      typeof value === 'number' || typeof value === 'string'
        ? { value }
        : (value as Observation[string])
  }
  return out
}

test('every condition case answers exactly as the server does', () => {
  expect(cases.conditions.length).toBeGreaterThan(20)
  for (const c of cases.conditions) {
    const got = evaluate(c.condition, observation(c.now), c.previous === null ? null : observation(c.previous))
    expect(`${c.name}: ${got}`).toBe(`${c.name}: ${c.expect}`)
  }
})

test('every parse case is accepted or refused exactly as the server does', () => {
  expect(cases.parse.length).toBeGreaterThan(15)
  for (const c of cases.parse) {
    if (c.expect.ok) {
      expect(`${c.name}: ${JSON.stringify(parse(c.document))}`).toBe(`${c.name}: ${JSON.stringify(c.expect.normalised)}`)
    } else {
      expect(() => parse(c.document)).toThrow(ConditionError)
    }
  }
})

describe('neverWithin: quiet over a summary', () => {
  const bar = (value: number, low: number, high: number) => ({ price: sample(value, low, high), spread: sample(0.0001) })
  const prev = (value: number) => ({ price: sample(value) })

  test('a threshold the band does not reach is quiet; one it reaches is not', () => {
    expect(neverWithin({ field: 'price', op: '>=', value: 1.2 }, bar(1.1, 1.09, 1.15))).toBe(true)
    expect(neverWithin({ field: 'price', op: '>=', value: 1.15 }, bar(1.1, 1.09, 1.15))).toBe(false)
    expect(neverWithin({ field: 'price', op: '<', value: 1.08 }, bar(1.1, 1.09, 1.15))).toBe(true)
    expect(neverWithin({ field: 'price', op: '<=', value: 1.09 }, bar(1.1, 1.09, 1.15))).toBe(false)
  })

  test('a crossing needs the level outside the band AND the reading before on the same side', () => {
    const crosses = { field: 'price', op: 'crosses', value: 1.2 }
    expect(neverWithin(crosses, bar(1.1, 1.09, 1.15), prev(1.12))).toBe(true)
    // Below the band now, above it before: the span opened across it.
    expect(neverWithin(crosses, bar(1.1, 1.09, 1.15), prev(1.21))).toBe(false)
    expect(neverWithin(crosses, bar(1.1, 1.09, 1.21), prev(1.12))).toBe(false)
    // No reading before: the first inside the span seeds it, and the rest stay inside the band.
    expect(neverWithin(crosses, bar(1.1, 1.09, 1.15), null)).toBe(true)
    expect(neverWithin({ field: 'price', op: 'crosses_below', value: 1.0 }, bar(1.1, 1.09, 1.15), prev(1.1))).toBe(true)
  })

  test('a level within the slack of the band is not quiet', () => {
    expect(neverWithin({ field: 'price', op: '>', value: 1.15001 }, bar(1.1, 1.09, 1.15))).toBe(false)
  })

  test('what reads the value alone, or has no band, proves nothing', () => {
    expect(neverWithin({ field: 'spread', op: '>', value: 0.001 }, bar(1.1, 1.09, 1.15))).toBe(false)
    expect(neverWithin({ field: 'price', op: 'inside', value: [1.3, 1.4] }, bar(1.1, 1.09, 1.15))).toBe(false)
    expect(neverWithin({ field: 'price', op: 'changed' }, bar(1.1, 1.09, 1.15), prev(1.1))).toBe(false)
    expect(neverWithin({ not: { field: 'price', op: '<', value: 1.0 } }, bar(1.1, 1.09, 1.15))).toBe(false)
  })

  test('all: quiet when any term is; any: when every term is; a field not carried never holds', () => {
    const far = { field: 'price', op: '>', value: 1.3 }
    const near = { field: 'price', op: '>', value: 1.12 }
    expect(neverWithin({ all: [near, far] }, bar(1.1, 1.09, 1.15))).toBe(true)
    expect(neverWithin({ any: [near, far] }, bar(1.1, 1.09, 1.15))).toBe(false)
    expect(neverWithin({ any: [far, { field: 'volume', op: '>', value: 1 }] }, bar(1.1, 1.09, 1.15))).toBe(true)
  })
})
